// Cloudflare Worker: หน้าเว็บ + API /api/queues (ต้อง bind D1 ชื่อ DB)
const MAX_DAILY = 4;
const json = (o, s = 200) =>
  new Response(JSON.stringify(o), {
    status: s,
    headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' }
  });

async function ensure(db) {
  await db.prepare(
    'CREATE TABLE IF NOT EXISTS queues (id TEXT PRIMARY KEY, date TEXT NOT NULL, time TEXT NOT NULL, status TEXT NOT NULL DEFAULT \'waiting\', data TEXT NOT NULL, updated_at INTEGER NOT NULL)'
  ).run();
}

async function listAll(db) {
  const { results } = await db.prepare('SELECT data FROM queues ORDER BY date, time').all();
  return results.map(r => JSON.parse(r.data));
}

async function handleGet(env, admin) {
  if (!env.DB) return json({ error: 'D1 binding "DB" not found' }, 500);
  await ensure(env.DB);
  return json({ queues: view(admin, await listAll(env.DB)) });
}

// body: { upserts: [queue...], deletes: [id...], replaceAll?: [queue...] }
async function handlePost(env, request, admin) {
  if (!env.DB) return json({ error: 'D1 binding "DB" not found' }, 500);
  const db = env.DB;
  await ensure(db);
  let body;
  try { body = await request.json(); } catch (e) { return json({ error: 'bad json' }, 400); }

  const conflicts = [];
  const now = Date.now();
  const stmts = [];
  const clean = q => ({
    id: String(q.id).slice(0, 80),
    queueNo: String(q.queueNo || '').slice(0, 20),
    date: String(q.date || '').slice(0, 10),
    time: String(q.time || '').slice(0, 5),
    customerName: String(q.customerName || '').slice(0, 120),
    phone: String(q.phone || '').slice(0, 40),
    serviceIds: Array.isArray(q.serviceIds) ? q.serviceIds.map(String).slice(0, 20) : [],
    price: Number(q.price) || 0,
    durationMins: Number(q.durationMins) || 45,
    drink: String(q.drink || '').slice(0, 80),
    note: String(q.note || '').slice(0, 500),
    status: String(q.status || 'waiting').slice(0, 20)
  });
  const put = q =>
    db.prepare(
      'INSERT INTO queues (id,date,time,status,data,updated_at) VALUES (?,?,?,?,?,?) ' +
      'ON CONFLICT(id) DO UPDATE SET date=excluded.date,time=excluded.time,status=excluded.status,data=excluded.data,updated_at=excluded.updated_at'
    ).bind(q.id, q.date, q.time, q.status, JSON.stringify(q), now);

  if (admin && Array.isArray(body.replaceAll)) {
    stmts.push(db.prepare('DELETE FROM queues'));
    body.replaceAll.forEach(q => stmts.push(put(clean(q))));
  } else {
    for (const raw of body.upserts || []) {
      const q = clean(raw);
      if (!admin) { q.status = 'waiting'; if (await db.prepare('SELECT 1 x FROM queues WHERE id=?').bind(q.id).first()) continue; }
      if (!q.id || !q.date || !q.time) continue;
      if (q.status !== 'cancelled') {
        const { results } = await db
          .prepare("SELECT id, time FROM queues WHERE date=? AND status!='cancelled' AND id!=?")
          .bind(q.date, q.id).all();
        if (results.some(r => r.time === q.time)) { conflicts.push({ id: q.id, reason: 'slot' }); continue; }
        if (results.length >= MAX_DAILY) { conflicts.push({ id: q.id, reason: 'full' }); continue; }
      }
      stmts.push(put(q));
    }
    for (const id of (admin ? body.deletes : []) || []) {
      stmts.push(db.prepare('DELETE FROM queues WHERE id=?').bind(String(id)));
    }
  }
  if (stmts.length) await db.batch(stmts);
  return json({ ok: true, conflicts, queues: view(admin, await listAll(db)) });
}


const PASS = env => String(env.ADMIN_PASSWORD || '2114');
async function sign(env, p) {
  const k = await crypto.subtle.importKey('raw', new TextEncoder().encode('somsom|' + PASS(env)), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return btoa(String.fromCharCode(...new Uint8Array(await crypto.subtle.sign('HMAC', k, new TextEncoder().encode(p)))));
}
async function isAdmin(env, req) {
  const [e, sig] = (req.headers.get('Authorization') || '').replace('Bearer ', '').split('.');
  return !!(e && sig && Number(e) > Date.now() && (await sign(env, e)) === sig);
}
const view = (admin, list) => admin ? list : list.map(q => ({ id: q.id, queueNo: q.queueNo, date: q.date, time: q.time, status: q.status, durationMins: q.durationMins, serviceIds: [], price: 0, customerName: '', phone: '', drink: '', note: '' }));

async function cfgGet(db) {
  await db.prepare('CREATE TABLE IF NOT EXISTS settings (k TEXT PRIMARY KEY, v TEXT NOT NULL)').run();
  const r = await db.prepare("SELECT v FROM settings WHERE k='config'").first();
  return r ? JSON.parse(r.v) : { services: {}, announcement: '' };
}

const PAGE_HEADERS = {
  'Content-Type': 'text/html; charset=utf-8',
  'Cache-Control': 'public, max-age=0, must-revalidate',
  'X-Content-Type-Options': 'nosniff',
  'X-Frame-Options': 'SAMEORIGIN',
  'Referrer-Policy': 'strict-origin-when-cross-origin'
};

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const p = url.pathname;
    if (p.startsWith('/api/')) {
      try {
        if (!env.DB) return json({ error: 'D1 binding "DB" not found' }, 500);
        const admin = await isAdmin(env, request);
        if (p === '/api/login' && request.method === 'POST') {
          const b = await request.json().catch(() => ({}));
          if (String(b.password) !== PASS(env)) return json({ error: 'รหัสผ่านไม่ถูกต้อง' }, 401);
          const e = String(Date.now() + 12 * 3600 * 1000);
          return json({ token: e + '.' + (await sign(env, e)) });
        }
        if (p === '/api/config') {
          if (request.method === 'GET') return json(await cfgGet(env.DB));
          if (!admin) return json({ error: 'unauthorized' }, 401);
          const b = await request.json().catch(() => ({}));
          const cfg = { services: b.services || {}, announcement: String(b.announcement || '').slice(0, 300) };
          await cfgGet(env.DB);
          await env.DB.prepare("INSERT INTO settings (k,v) VALUES ('config',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v").bind(JSON.stringify(cfg)).run();
          return json(cfg);
        }
        if (p === '/api/queues') {
          if (request.method === 'GET') return await handleGet(env, admin);
          if (request.method === 'POST') return await handlePost(env, request, admin);
        }
        return json({ error: 'not found' }, 404);
      } catch (e) {
        return json({ error: String(e && e.message || e) }, 500);
      }
    }
    if (p === '/favicon.ico') return new Response(null, { status: 204 });
    if (request.method !== 'GET' && request.method !== 'HEAD') return new Response('Method Not Allowed', { status: 405 });
    return new Response(request.method === 'HEAD' ? null : HTML, { headers: PAGE_HEADERS });
  }
};

